γ : Instance
hv : γ.Valid
j : ℕ
hj : j < γ.nodes.length
ids : List ℕ
hids : ∀ a < j, ids.getD a 0 = γ.rep hv a
⊢ (have sg := sigWith ids (γ.nodes.getD j (Node.src 0));
    have r := firstIndex (fun i => decide (sigWith ids (γ.nodes.getD i (Node.src 0)) = sg)) j;
    if r < j then ids.getD r 0 else j) =
    γ.rep hv j
